static juce::var object(){return juce::var(new juce::DynamicObject());}
static void add(juce::var& o,const char* k,const juce::var& v){o.getDynamicObject()->setProperty(k,v);}
// Deliberately independent: one sin/cos evaluation per original tap, unlike
// production's host-rate complex recurrence; no production response helper.
static C originalDTFT(const float* taps,double hz){C sum{};for(int n=0;n<1024;++n){const double a=-6.283185307179586476925286766559*hz*n/44100.;sum+=(double)taps[n]*C(std::cos(a),std::sin(a));}return sum;}
static C expectedCorrection(const float* taps,double rate,int delay,double hz,double degree){const double a=-6.283185307179586476925286766559*hz*delay/rate;const C dry(std::cos(a),std::sin(a));return dry*((1-degree*.01)+degree*.01*originalDTFT(taps,hz));}
static C independentHostDTFT(const HostRateIR& model,double hz){C sum{};for(std::size_t n=0;n<model.coefficients.size();++n){const double a=-6.283185307179586476925286766559*hz*(double)n/model.sampleRate;sum+=(double)model.coefficients[n]*C(std::cos(a),std::sin(a));}return sum;}
static C expectedActualCorrection(const HostRateIR& model,double hz,double degree){const double a=-6.283185307179586476925286766559*hz*model.latencySamples/model.sampleRate;return C(std::cos(a),std::sin(a))*(1-degree*.01)+independentHostDTFT(model,hz)*(degree*.01);}
static void process(HonestMixAudioProcessor& p,juce::AudioBuffer<float>& b,bool bypass=false){juce::MidiBuffer midi;audioCounting=true;if(bypass)p.processBlockBypassed(b,midi);else p.processBlock(b,midi);audioCounting=false;}
static void silence(HonestMixAudioProcessor& p,int blocks=32){juce::AudioBuffer<float> b(2,256);for(int n=0;n<blocks;++n){b.clear();process(p,b);}}
static C sine(HonestMixAudioProcessor& p,double rate,double frequency,int channel=0,bool bypass=false){
 juce::AudioBuffer<float> b(2,256);const double w=6.283185307179586476925286766559*frequency/rate,amp=.0001;
 const int warm=((int)std::max(8192.,rate*.025+rate*.030)+255)/256*256,total=warm+8192;double cc=0,ss=0,cs=0,yc=0,ys=0;
 for(int start=0;start<total;start+=256){for(int i=0;i<256;++i){b.setSample(0,i,(float)(amp*std::cos(w*(start+i))));b.setSample(1,i,0);}process(p,b,bypass);
  if(start>=warm)for(int i=0;i<256;++i){const double c=std::cos(w*(start+i)),s=std::sin(w*(start+i)),y=b.getSample(channel,i);cc+=c*c;ss+=s*s;cs+=c*s;yc+=y*c;ys+=y*s;}}
 const double d=cc*ss-cs*cs;return C((yc*ss-ys*cs)/d,-(ys*cc-yc*cs)/d)/amp;
}
struct Metrics{double graphDb=0,audioDb=0,phase=0,absoluteComplex=0,basisError=0,denseError=0,denseSpacing=0;int graphPoints=0,sineCases=0,denseOraclePoints=0;};
static void validateDense(const CorrectionResponseSnapshot& s,const CorrectionResponseBasis& dense,Metrics& m){
 check(dense.generation==s.generation&&dense.sampleRate==s.sampleRate&&dense.frequencies.front()==20&&dense.frequencies.back()==std::min(20000.,std::nextafter(s.sampleRate*.5,0.)),"Dense FFT metadata and exact graph boundaries must match snapshot");
 for(std::size_t i=1;i<dense.frequencies.size();++i){const double spacing=dense.frequencies[i]-dense.frequencies[i-1];m.denseSpacing=std::max(m.denseSpacing,spacing);check(spacing>0&&spacing<=1.000000001,"Dense FFT graph spacing must remain <=1Hz");}
 auto test=[&](std::size_t i,double degree){const auto expected=expectedActualCorrection(*s.activeIR,dense.frequencies[i],degree),actual=dense.evaluate(i,degree);const double error=std::abs(actual-expected);m.denseError=std::max(m.denseError,error);if(std::abs(expected)>1e-4)check(std::abs(20*std::log10(std::abs(actual/expected)))<=.01,"Dense double FFT must meet independent 0.01dB graph oracle");else check(error<2e-6,"Dense near-zero FFT response must meet absolute complex floor");++m.denseOraclePoints;};
 for(std::size_t k=0;k<131;++k)test(k*(dense.frequencies.size()-1)/130,100);
 // Search the entire dense rendered grid for the strongest peak and deepest
 // valley at every degree, then independently check all five adjacent bins.
 // This covers high-Q/extreme mixed responses rather than random bins alone.
 for(double degree:{0.,25.,50.,75.,100.,125.,150.,175.,200.}){std::size_t minimum=0,maximum=0;double low=std::numeric_limits<double>::infinity(),high=-1;for(std::size_t i=0;i<dense.frequencies.size();++i){double amplitude=std::norm(dense.evaluate(i,degree));if(amplitude<low){low=amplitude;minimum=i;}if(amplitude>high){high=amplitude;maximum=i;}}for(auto index:{minimum,maximum})for(int offset=-2;offset<=2;++offset){const auto nearby=(long long)index+offset;if(nearby>=0&&nearby<(long long)dense.frequencies.size())test((std::size_t)nearby,degree);}}
}
static juce::var responseTests(){
 Metrics m;juce::Array<juce::var> rows;
 for(int profile:{0,1,924,802,730,756,1572})for(double rate:{44100.,48000.,96000.,192000.}){
  HonestMixAudioProcessor p;p.setProfileIndex(profile);p.prepareToPlay(rate,256);auto initial=p.captureResponseState();check(initial.audioReady&&initial.activeProfile==profile&&initial.profilePhase==ProfilePhase::Stable,"Prepared active IR must be immediately truthful");
  std::vector<double> hz;for(int i=0;i<97;++i)hz.push_back(20*std::pow(1000.,(i+.37)/97.));
  auto basis=initial.buildBasis(hz);const auto dense=hm::plot::buildBasis(initial);validateDense(initial,dense,m);double rowGraph=0,rowAudio=0,rowPhase=0;
  for(float degree:{0.f,25.f,50.f,75.f,100.f,125.f,150.f,175.f,200.f}){
   p.setTranslationDegree(degree);silence(p,(int)std::ceil(rate*.025/256)+2);auto snapshot=p.captureResponseState();check(!snapshot.degreeTransition&&std::abs(snapshot.appliedDegree-degree)<1e-6,"Applied degree must reach quantized target after real 20ms audio ramp");
   for(std::size_t i=0;i<hz.size();++i){const C expected=expectedActualCorrection(*initial.activeIR,hz[i],degree),actual=snapshot.evaluateCorrectionResponse(hz[i]),cached=basis.evaluate(i,degree);const double linear=std::abs(actual-expected);m.absoluteComplex=std::max(m.absoluteComplex,linear);m.basisError=std::max(m.basisError,std::abs(actual-cached));check(std::abs(actual-cached)<1e-11*(1+std::abs(actual)),"Basis must use the same immutable exact complex transfer");
    if(std::abs(expected)>1e-4){double error=std::abs(20*std::log10(std::abs(actual/expected)));rowGraph=std::max(rowGraph,error);check(error<=.01,"Graph absolute gain error exceeds 0.01dB");}else check(linear<2e-6,"Deep graph null absolute complex error exceeds its independent floor");++m.graphPoints;}
   for(double f:{20.,997.,1135.,10000.,19937.}){const C expected=expectedActualCorrection(*initial.activeIR,f,degree),actual=sine(p,rate,f);const double linear=std::abs(actual-expected);if(std::abs(expected)>1e-4){const double db=std::abs(20*std::log10(std::abs(actual/expected))),phase=std::abs(std::arg(actual/expected));rowAudio=std::max(rowAudio,db);rowPhase=std::max(rowPhase,phase);check(db<=.02&&phase<=.001,"Actual steady sine absolute gain/phase contract failed");}else check(linear<2e-5,"Deep audio null absolute complex error exceeds its independent floor");++m.sineCases;}
  }
  auto row=object();add(row,"profile",profile);add(row,"sampleRate",rate);add(row,"graphDb",rowGraph);add(row,"audioDb",rowAudio);add(row,"phaseRadians",rowPhase);add(row,"degrees",9);add(row,"passed",true);rows.add(row);m.graphDb=std::max(m.graphDb,rowGraph);m.audioDb=std::max(m.audioDb,rowAudio);m.phase=std::max(m.phase,rowPhase);std::cout<<profile<<" @ "<<rate<<" graph="<<rowGraph<<" audio="<<rowAudio<<" phase="<<rowPhase<<std::endl;
 }
 // A real mathematical cancellation is retained as complex zero, with no dB
 // floor injected into production. Near-zero imaginary phase remains visible.
 auto synthetic=std::make_shared<HostRateIR>();synthetic->sampleRate=44100;synthetic->coefficients={-1.f};CorrectionResponseSnapshot null;null.activeIR=synthetic;null.sampleRate=44100;null.appliedDegree=50;check(std::abs(null.evaluateCorrectionResponse(1234.567))<1e-15,"Exact mixed cancellation must remain zero");synthetic->coefficients={-1.f,1e-7f};const C expected=C(.5,0)+.5*(C(-1,0)+1e-7*std::polar(1.,-6.283185307179586476925286766559*1234.567/44100.));check(std::abs(null.evaluateCorrectionResponse(1234.567)-expected)<1e-15,"Deep null phase must not be replaced by a graph floor");
 HonestMixAudioProcessor low;low.prepareToPlay(32000,256);auto boundary=low.captureResponseState();check(boundary.validFrequency(15999.999)&&!boundary.validFrequency(16000)&&!boundary.validFrequency(20000)&&!boundary.validFrequency(-1)&&!boundary.validFrequency(std::numeric_limits<double>::quiet_NaN()),"32k response must stop strictly below Nyquist");check(std::abs(boundary.evaluateCorrectionResponse(16000))==0,"Invalid graph frequency must not alias into audible range");
 auto result=object();add(result,"rows",rows);add(result,"graphDb",m.graphDb);add(result,"audioDb",m.audioDb);add(result,"phaseRadians",m.phase);add(result,"maximumAbsoluteComplexError",m.absoluteComplex);add(result,"basisError",m.basisError);add(result,"denseFftAbsoluteError",m.denseError);add(result,"denseFftMaximumSpacingHz",m.denseSpacing);add(result,"denseFftIndependentOraclePoints",m.denseOraclePoints);add(result,"graphPoints",m.graphPoints);add(result,"actualSineCases",m.sineCases);add(result,"deepNullAbsoluteFloor",true);add(result,"nyquist32k",true);add(result,"passed",true);return result;
}
struct Listener final:juce::AudioProcessorListener{int begin=0,end=0,values=0;void audioProcessorParameterChanged(juce::AudioProcessor*,int,float)override{++values;}void audioProcessorChanged(juce::AudioProcessor*,const ChangeDetails&)override{}void audioProcessorParameterChangeGestureBegin(juce::AudioProcessor*,int)override{++begin;}void audioProcessorParameterChangeGestureEnd(juce::AudioProcessor*,int)override{++end;}};
struct Tempo final:juce::AudioPlayHead{double value=123.456;bool valid=true;juce::Optional<PositionInfo> getPosition()const override{PositionInfo p;if(valid)p.setBpm(value);return p;}};
static juce::var parameterTempoTests(){
 HonestMixAudioProcessor p;Listener l;p.addListener(&l);p.beginTranslationGesture();p.beginTranslationGesture();for(float v:{100.1f,100.24f,100.26f,49.8f,0.f,200.f}){p.setTranslationDegree(v);check(p.getTranslationDegree()==std::round(juce::jlimit(0.f,200.f,v)*2)*.5f,"Readback must match legal 0.5 parameter quantization");}p.endTranslationGesture();p.endTranslationGesture();check(l.begin==1&&l.end==1,"A complete drag must create exactly one host gesture pair");p.setTranslationDegree(73.7f);check(l.begin==2&&l.end==2&&p.getTranslationDegree()==73.5f,"Discrete edit must create its own pair and exact quantized readback");p.removeListener(&l);
 p.setTranslationDegree(0);p.prepareToPlay(48000,48);p.setTranslationDegree(200);auto before=p.captureResponseState();check(before.targetDegree==200&&before.appliedDegree==0&&before.degreeTransition,"Pending host target must never masquerade as applied audio degree");juce::AudioBuffer<float> block(2,48);double previous=0;for(int k=0;k<20;++k){block.clear();process(p,block);const auto s=p.captureResponseState();check(s.appliedDegree>=previous&&std::abs(s.appliedDegree-(k+1)*10)<.01,"Published applied endpoint must follow actual 20ms linear smoother");check((k==19)==!s.degreeTransition,"Smoothing flag must mark the real final sample");previous=s.appliedDegree;}
 Tempo tempo;p.setPlayHead(&tempo);for(double bpm:{1.,60.,90.,117.5,123.456,300.,1000.,.5,1000.25,1e300}){tempo.value=bpm;block.clear();process(p,block);const auto s=p.getHostBpmSnapshot();check(s.valid&&s.fresh&&s.bpm==bpm&&p.getHostBpm()==bpm,"Host BPM must retain exact double source without transient or clamping");check(s.calculable==(bpm>=1&&bpm<=1000),"Calculability must explicitly bound 1..1000 while retaining legal host BPM");}
 for(double invalid:{0.,-1.,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){tempo.value=invalid;block.clear();process(p,block);const auto s=p.getHostBpmSnapshot();check(!s.valid&&!s.calculable&&p.getHostBpm()==0,"Invalid host BPM must never silently become 120");}
 tempo.value=123.456;block.clear();process(p,block);juce::Thread::sleep(3);check(!p.getHostBpmSnapshot(1).fresh,"Stopped callbacks must expose stale host tempo");tempo.valid=false;block.clear();process(p,block);check(!p.getHostBpmSnapshot().valid,"Missing host BPM must invalidate source");tempo.valid=true;block.clear();process(p,block);p.releaseResources();check(!p.getHostBpmSnapshot().valid&&!p.captureResponseState().audioReady,"Release must invalidate host and audio status");p.prepareToPlay(96000,48);check(!p.getHostBpmSnapshot().valid,"Prepare must not reuse old host tempo");
 auto result=object();add(result,"quantizedReadback",true);add(result,"dragGesturePairs",1);add(result,"discreteGesturePairs",1);add(result,"applied20msEndpoint",true);add(result,"doubleHostTempo",true);add(result,"freshnessAndRange",true);add(result,"passed",true);return result;
}
static juce::var switchingTests(){
 HonestMixAudioProcessor p;p.prepareToPlay(48000,64);juce::AudioBuffer<float> b(2,64);const float amp=.0001f;auto tick=[&]{for(int ch=0;ch<2;++ch)for(int i=0;i<64;++i)b.setSample(ch,i,amp);process(p,b);};for(int i=0;i<100;++i)tick();const auto old=p.captureResponseState();p.setProfileIndex(924);auto pending=p.captureResponseState();check(pending.requestedProfile==924&&pending.activeProfile==0&&pending.profilePhase==ProfilePhase::Preparing,"Request must remain distinct from active until real audio adoption");
 bool warming=false,fading=false,stable=false;double endpointError=0;const auto deadline=juce::Time::getMillisecondCounterHiRes()+10000;
 while(juce::Time::getMillisecondCounterHiRes()<deadline){tick();auto s=p.captureResponseState();check(s.generation==s.activeIR->generation&&s.activeProfile==s.activeIR->profile,"Snapshot token must identify its actual immutable model");if(s.profilePhase==ProfilePhase::Warming||s.profilePhase==ProfilePhase::Fading){check(s.activeProfile==0&&s.generation==old.generation&&s.incomingProfile==924,"Active token must not commit during warming or fading");warming|=s.profilePhase==ProfilePhase::Warming;fading|=s.profilePhase==ProfilePhase::Fading;}
  if(s.profilePhase==ProfilePhase::Warming||s.profilePhase==ProfilePhase::Fading||s.activeProfile==924){const double expected=s.evaluateCorrectionResponse(0).real()*amp;endpointError=std::max(endpointError,std::abs(b.getSample(0,63)-expected));check(std::abs(b.getSample(0,63)-expected)<3e-6,"Reported fade endpoint must equal the actual continuous DC output endpoint");}
  if(s.profilePhase==ProfilePhase::Stable&&s.activeProfile==924){stable=true;break;}juce::Thread::sleep(1);
 }
 check(warming&&fading&&stable,"Real full-IR warming, 20ms fading and committed stable state must all be observed");
 p.setProfileIndex(1);p.setProfileIndex(802);p.setProfileIndex(756);const auto rapidDeadline=juce::Time::getMillisecondCounterHiRes()+10000;while(juce::Time::getMillisecondCounterHiRes()<rapidDeadline){tick();auto s=p.captureResponseState();if(s.activeProfile==756&&s.profilePhase==ProfilePhase::Stable)break;juce::Thread::sleep(1);}check(p.captureResponseState().activeProfile==756&&p.captureResponseState().profilePhase==ProfilePhase::Stable,"Rapid latest profile request must become actual active audio");
 p.setProfileIndex(730);p.prepareToPlay(96000,64);auto reprepare=p.captureResponseState();check(reprepare.activeProfile==730&&reprepare.sampleRate==96000&&reprepare.latencySamples==279,"Rate prepare must reject stale worker bundle and publish actual new-rate coefficients");
 auto result=object();add(result,"preparingDistinctFromActive",true);add(result,"warmingObserved",warming);add(result,"fadingObserved",fading);add(result,"committedStable",stable);add(result,"dcEndpointError",endpointError);add(result,"rapidLatestWins",true);add(result,"ratePrepare",true);add(result,"passed",true);return result;
}
static juce::var monitorTests(){
 double maxError=0;for(auto mode:{ListenNormal,ListenMono,ListeniPhone,ListenCar}){HonestMixAudioProcessor p;p.setTranslationDegree(75);p.setListenMode(mode);p.prepareToPlay(48000,256);for(double hz:{80.,997.,10000.}){auto s=p.captureResponseState();const C correction=expectedCorrection(p.getDatabase().getProfileFIR(0),48000,p.getLatencySamples(),hz,75);const C z=std::polar(1.,-6.283185307179586476925286766559*hz/48000.);C diagonal=1,cross=0;if(mode==ListenMono){diagonal=.5;cross=.5;}if(mode==ListeniPhone||mode==ListenCar){const auto& c=s.monitorCoefficients[(std::size_t)mode];diagonal=((double)c[0]+(double)c[1]*z+(double)c[2]*z*z)/(1.+(double)c[3]*z+(double)c[4]*z*z);}
  const auto matrix=s.evaluateMonitorMatrix(hz);check(std::abs(matrix.ll-diagonal)<1e-12&&std::abs(matrix.lr-cross)<1e-12&&std::abs(matrix.rl-cross)<1e-12&&std::abs(matrix.rr-diagonal)<1e-12,"Post-correction monitor must expose the full stereo matrix");for(int ch:{0,1}){const auto actual=sine(p,48000,hz,ch),expected=correction*(ch==0?diagonal:cross);double error=std::abs(actual-expected)/(1+std::abs(expected));maxError=std::max(maxError,error);check(error<2e-5,"Actual monitor sine routing must match independent complex matrix");}}
 }
 auto result=object();add(result,"normalMonoPhoneCar",true);add(result,"fullStereoMatrix",true);add(result,"maximumRelativeLinearError",maxError);add(result,"passed",true);return result;
}
static juce::var failedLoadRetryTests(){
 HonestMixAudioProcessor p;p.prepareToPlay(48000,64);juce::AudioBuffer<float> b(2,64);p.setProfileIndex(1);const auto settleDeadline=juce::Time::getMillisecondCounterHiRes()+10000;while(juce::Time::getMillisecondCounterHiRes()<settleDeadline){b.clear();process(p,b);const auto s=p.captureResponseState();if(s.activeProfile==1&&s.profilePhase==ProfilePhase::Stable)break;juce::Thread::sleep(1);}const auto initial=p.captureResponseState();check(initial.activeProfile==1&&initial.profilePhase==ProfilePhase::Stable,"Fault setup must observe real completed worker preparation");
 // Fault the real immutable coefficient-vector allocation in the background
 // loader once. No production test seam and no mocked loading state.
 // Calibrate the real allocator request instead of assuming n*sizeof(float).
 // MSVC adds alignment metadata for vectors >=4096B (39B in x64 Release).
 std::vector<float> allocationProbe;probingVectorAllocation=true;allocationProbe.resize(initial.activeIR->coefficients.size());probingVectorAllocation=false;
 check(vectorAllocationBytes>=initial.activeIR->coefficients.size()*sizeof(float),"Coefficient allocation probe must observe the actual vector allocation");injectedAllocationBytes=0;failCoefficientBytes=vectorAllocationBytes;p.setProfileIndex(924);bool failed=false;
 const auto deadline=juce::Time::getMillisecondCounterHiRes()+10000;
 while(juce::Time::getMillisecondCounterHiRes()<deadline){b.clear();process(p,b);auto s=p.captureResponseState();if(s.profileError){check(s.activeProfile==1&&s.requestedProfile==924&&!p.isProfileLoading()&&s.profileErrorMessage.isNotEmpty(),"Failed load must retain old active IR and expose an error instead of endless loading");failed=true;break;}juce::Thread::sleep(1);}
 failCoefficientBytes=0;check(injectedAllocationBytes.load()==vectorAllocationBytes,"Calibrated coefficient allocation fault must actually fire");check(failed,"Real loader allocation fault must be caught and published");
 const auto failedGeneration=p.captureResponseState().requestedGeneration;for(int i=0;i<10;++i){b.clear();process(p,b);}check(p.captureResponseState().profileError&&p.captureResponseState().requestedGeneration==failedGeneration,"Audio callback must not retry failed loads in an uncontrolled loop");
 p.setProfileIndex(924);check(!p.captureResponseState().profileError&&p.captureResponseState().requestedGeneration>failedGeneration,"Explicit same-profile selection must issue a fresh retry token");
 const auto retryDeadline=juce::Time::getMillisecondCounterHiRes()+10000;bool recovered=false;while(juce::Time::getMillisecondCounterHiRes()<retryDeadline){b.clear();process(p,b);auto s=p.captureResponseState();if(s.activeProfile==924&&s.profilePhase==ProfilePhase::Stable){recovered=true;break;}juce::Thread::sleep(1);}check(recovered,"Same-profile retry must recover actual convolution and commit after fade");
 auto result=object();add(result,"realBackgroundAllocationFault",true);add(result,"coefficientBytes",(juce::int64)(initial.activeIR->coefficients.size()*sizeof(float)));add(result,"calibratedVectorNewBytes",(juce::int64)vectorAllocationBytes);add(result,"injectedNewBytes",(juce::int64)injectedAllocationBytes.load());add(result,"oldActiveRetained",true);add(result,"noAutomaticRetryLoop",true);add(result,"sameProfileExplicitRecovery",true);add(result,"passed",true);return result;
}
static juce::var bypassSnapshotTests(){
 double maximumError=0;for(double rate:{44100.,48000.,96000.,192000.}){HonestMixAudioProcessor p;p.setTranslationDegree(200);p.setListenMode(ListenCar);p.prepareToPlay(rate,256);for(double hz:{80.,1135.,19937.}){const auto actual=sine(p,rate,hz,0,true),expected=std::polar(1.,-6.283185307179586476925286766559*hz*p.getLatencySamples()/rate);const auto s=p.captureResponseState();check(s.bypassed,"Bypass must be explicitly published by the actual audio callback");const auto matrix=s.evaluateMonitorMatrix(hz);check(std::abs(matrix.ll-1.)<1e-15&&std::abs(matrix.rr-1.)<1e-15&&std::abs(matrix.lr)==0&&std::abs(matrix.rl)==0,"Bypass monitor stage must be identity");maximumError=std::max(maximumError,std::abs(actual-expected));check(std::abs(actual-expected)<2e-6&&std::abs(s.evaluateCorrectionResponse(hz)-expected)<1e-15,"Bypass snapshot and actual output must share exact reported dry delay");}}
 auto result=object();add(result,"maximumComplexError",maximumError);add(result,"delayedDryAndIdentityMonitor",true);add(result,"passed",true);return result;
}
