int main(int argc,char** argv){auto report=object();add(report,"hardwareAudioOpened",false);add(report,"version",JucePlugin_VersionString);add(report,"graphDbLimit",.01);add(report,"audioDbLimit",.02);add(report,"phaseLimitRadians",.001);add(report,"deepNullThresholdLinear",1e-4);add(report,"oracle","Independent direct double sin/cos DTFT of actual submitted host-rate coefficients; original-44.1k SRC absolute fidelity remains in separate unchanged stricter FidelityCheck");try{add(report,"parametersAndTempo",parameterTempoTests());add(report,"actualProfileSwitch",switchingTests());add(report,"failedLoadRetry",failedLoadRetryTests());add(report,"monitor",monitorTests());add(report,"bypassSnapshot",bypassSnapshotTests());add(report,"response",responseTests());add(report,"headphonePrediction",predictionTests());check(audioNews==0,"Actual processBlock allocated C++ memory");add(report,"audioCppNews",(juce::int64)audioNews);add(report,"passed",true);}catch(const std::exception& e){audioCounting=false;add(report,"passed",false);add(report,"error",e.what());std::cerr<<e.what()<<std::endl;}if(argc>1)juce::File(juce::String::fromUTF8(argv[1])).replaceWithText(juce::JSON::toString(report));return (bool)report["passed"]?0:1;}
